```python
import sys
import math
from bisect import bisect_left, bisect_right

LIMIT = 2 * 10**9

def isqrt(x):
    """兼容旧版本 Python 的整数平方根"""
    r = int(math.sqrt(x))
    while (r + 1) * (r + 1) <= x:
        r += 1
    while r * r > x:
        r -= 1
    return r

def sieve(n):
    """筛出 1~n 的所有素数"""
    vis = [False] * (n + 1)
    primes = []
    for i in range(2, n + 1):
        if not vis[i]:
            primes.append(i)
        for p in primes:
            if i * p > n:
                break
            vis[i * p] = True
            if i % p == 0:
                break
    return primes

# 预处理到 sqrt(2e9) 即可
BASE_PRIMES = sieve(isqrt(LIMIT))

def build_extra():
    """预处理所有 a>=2 的特殊素数幂"""
    exponents = [2, 4, 6, 10, 12, 16, 18, 22, 28, 30]
    extra = set()

    max_base = isqrt(LIMIT)
    for p in BASE_PRIMES:
        if p > max_base:
            break
        for a in exponents:
            val = 1
            ok = True
            for _ in range(a):
                if val > LIMIT // p:
                    ok = False
                    break
                val *= p
            if not ok:
                break
            extra.add(val)

    return sorted(extra)

extra_nums = build_extra()

def count_primes_in_range(l, r):
    """分段筛统计区间 [l, r] 内素数个数"""
    size = r - l + 1
    is_prime_seg = [True] * size

    if l == 1:
        is_prime_seg[0] = False

    for p in BASE_PRIMES:
        if p * p > r:
            break
        start = max(p * p, ((l + p - 1) // p) * p)
        for x in range(start, r + 1, p):
            is_prime_seg[x - l] = False

    return sum(is_prime_seg)

def count_implicit_primes(l, r):
    """统计区间 [l, r] 内隐式素数个数"""
    # 1. 统计素数个数（对应 a=1）
    ans = count_primes_in_range(l, r)

    # 2. 统计特殊素数幂（对应 a>=2）
    ans += bisect_right(extra_nums, r) - bisect_left(extra_nums, l)

    return ans

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        l = int(data[idx])
        r = int(data[idx + 1])
        idx += 2
        out.append(str(count_implicit_primes(l, r)))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
```

