        for (int i = 2; (long) i * i <= MAXN; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= MAXN; j += i) {
                    isPrime[j] = false;
                }
            }
        }
        int cnt = 0;
        for (int i = 2; i <= MAXN; i++) {
            if (isPrime[i]) {
                primes.add(i);
                cnt++;
            }
            piSmall[i] = cnt;
        }
